import{_ as a,o,c as s,a3 as n}from"./chunks/framework.Cc-oPviL.js";const c=JSON.parse('{"title":"学习方法论：怎么把枯燥的知识连起来","description":"","frontmatter":{},"headers":[],"relativePath":"bagu/plan/02.md","filePath":"bagu/plan/02.md"}'),e={name:"bagu/plan/02.md"};function r(l,t,d,i,p,h){return o(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="学习方法论-怎么把枯燥的知识连起来" tabindex="-1">学习方法论：怎么把枯燥的知识连起来 <a class="header-anchor" href="#学习方法论-怎么把枯燥的知识连起来" aria-label="Permalink to &quot;学习方法论：怎么把枯燥的知识连起来&quot;">​</a></h1><blockquote><p>这一篇不讲知识点，讲<strong>怎么学</strong>。如果只看一篇，看这篇。 因为八股文的差距从来不在&quot;背了多少&quot;，在&quot;能不能解释为什么&quot;。</p></blockquote><h2 id="零、先说一个判断" tabindex="-1">零、先说一个判断 <a class="header-anchor" href="#零、先说一个判断" aria-label="Permalink to &quot;零、先说一个判断&quot;">​</a></h2><p>你说&quot;上过课但忘了&quot;。这几乎不是记忆力问题，而是<strong>当初学的时候，每个概念都是独立存进去的</strong>。</p><p>孤立的知识点，遗忘曲线非常陡——两周掉一半。 有挂钩的知识点，掉不下去——因为你会从别的概念把它拽回来。</p><p>所以后面所有方法，目标只有一个：<strong>给每个新概念至少装三个钩子</strong>。</p><table tabindex="0"><thead><tr><th>钩子类型</th><th>挂什么</th><th>例子</th></tr></thead><tbody><tr><td>向上挂</td><td>它解决了什么麻烦</td><td>虚拟内存 → 解决&quot;内存不够 + 进程互相踩&quot;</td></tr><tr><td>横向挂</td><td>它和谁是同一类、谁是它的反面</td><td>epoll ↔ select（同目标，不同实现）</td></tr><tr><td>向下挂</td><td>它的代价是什么</td><td>虚拟内存 → 每次访存多一次地址翻译</td></tr></tbody></table><p>一个概念能回答这三问，基本就忘不掉了。</p><hr><h2 id="一、类比域复用-不是-打个比方-是-建一套世界观" tabindex="-1">一、类比域复用（不是&quot;打个比方&quot;，是&quot;建一套世界观&quot;） <a class="header-anchor" href="#一、类比域复用-不是-打个比方-是-建一套世界观" aria-label="Permalink to &quot;一、类比域复用（不是&quot;打个比方&quot;，是&quot;建一套世界观&quot;）&quot;">​</a></h2><h3 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h3><p>不要为每个知识点临时找一个巧妙的比喻。<strong>全库只用三套类比域，一用到底</strong>：</p><table tabindex="0"><thead><tr><th>类比域</th><th>对应模块</th><th>映射表</th></tr></thead><tbody><tr><td><strong>餐厅</strong></td><td>操作系统</td><td>CPU = 灶台（只有一个，谁抢到谁能炒）；进程 = 一桌客人的订单（有独立的食材和进度）；线程 = 同一桌订单里的几道菜，共用灶台和食材；内存 = 操作台（有限，摆不下就收进仓库）；磁盘 = 后厨仓库（大但慢）；调度 = 排号叫号；缺页中断 = 客人点了一道操作台上没有的菜，得去仓库取</td></tr><tr><td><strong>快递</strong></td><td>计算机网络</td><td>IP = 收件地址；MAC = 这栋楼的门牌；TCP = 带签收和重发的快递单；UDP = 塞进信箱就走；DNS = 查地址簿；路由 = 分拣中心；HTTP = 包裹里装的东西；TLS = 上锁的箱子</td></tr><tr><td><strong>图书馆</strong></td><td>数据库</td><td>表 = 一个书架；行 = 一本书；索引 = 索引柜的卡片（另存一份，按序排好）；事务 = 一次借还流程（要么全办完，要么都不算）；锁 = 借出登记本；MVCC = 同一本书存了多个版本的副本，各看各的</td></tr></tbody></table><h3 id="为什么有效" tabindex="-1">为什么有效 <a class="header-anchor" href="#为什么有效" aria-label="Permalink to &quot;为什么有效&quot;">​</a></h3><p>记忆负担来自<strong>映射关系的数量</strong>。如果每个知识点配一个新比喻，你要记 N 套映射； 一套类比域用到底，你只记 1 套映射，然后把新概念往格子里塞。<strong>塞不进去的地方，往往就是你还没真懂的地方</strong>——这反而是个免费的自检工具。</p><h3 id="什么时候失效" tabindex="-1">什么时候失效 <a class="header-anchor" href="#什么时候失效" aria-label="Permalink to &quot;什么时候失效&quot;">​</a></h3><ol><li><strong>类比只覆盖主干，不覆盖细节</strong>。比如&quot;内存 = 操作台&quot;，但内存还有缓存一致性、TLB、页表这些操作台没有的东西。遇到细节必须切回真实机制，别硬套。</li><li><strong>同一个词在两套类比域里含义冲突</strong>。所以本库规定：餐厅只管 OS，快递只管网络，不混用。</li><li><strong>类比的边界要写下来</strong>。每篇末尾的「类比失效处」就是干这个的——不写，你会把类比的结论当成事实。</li></ol><hr><h2 id="二、追问三层法-八股文的分水岭" tabindex="-1">二、追问三层法（八股文的分水岭） <a class="header-anchor" href="#二、追问三层法-八股文的分水岭" aria-label="Permalink to &quot;二、追问三层法（八股文的分水岭）&quot;">​</a></h2><p>同一个知识点，三个层次答出来，面试官给的评价完全不同：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第 1 层：是什么           &lt; 背了就会，人人都有，不加分</span></span>
<span class="line"><span>    v 追问&quot;为什么&quot;</span></span>
<span class="line"><span>第 2 层：为什么这么设计    &lt; 拉开差距的地方</span></span>
<span class="line"><span>    v 追问&quot;不这样呢&quot;</span></span>
<span class="line"><span>第 3 层：不这么做会怎么坏  &lt; 只有真懂的人答得出</span></span></code></pre></div><h3 id="举个完整的例子" tabindex="-1">举个完整的例子 <a class="header-anchor" href="#举个完整的例子" aria-label="Permalink to &quot;举个完整的例子&quot;">​</a></h3><p><strong>第 1 层</strong>：TCP 建立连接要三次握手。 ——这是背书，任何人都会。</p><p><strong>第 2 层</strong>：因为双方都要确认&quot;我发得出去、你收得到&quot;，还要确认&quot;你发得出去、我收得到&quot;。两次只能确认前者，第三次才能让<strong>服务端</strong>确认自己的发送能力。 ——开始有信息量了。</p><p><strong>第 3 层</strong>：如果只握手两次，服务端一发 SYN+ACK 就认为连接建立，此时若有个<strong>延迟到达的旧 SYN</strong>，服务端会白建一个连接、分配资源干等，而客户端根本不认这个连接。这就是&quot;两次握手会被历史连接骗走资源&quot;。三次握手让客户端多一次确认，正好把这个坑堵住。 ——这一层答出来，面试官会认为你真读过协议设计的动机，不是背的。</p><h3 id="怎么做-可操作" tabindex="-1">怎么做（可操作） <a class="header-anchor" href="#怎么做-可操作" aria-label="Permalink to &quot;怎么做（可操作）&quot;">​</a></h3><p>每读完一篇，逼自己写下这三行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>是什么：______</span></span>
<span class="line"><span>为什么这样：______</span></span>
<span class="line"><span>不这样会坏在：______</span></span></code></pre></div><p>第三行写不出来，就去搜&quot;XX 为什么这样设计&quot;或者&quot;XX 的缺陷&quot;。<strong>第三行才是这篇的真正内容</strong>。</p><hr><h2 id="三、反事实学习-把-设计-变成-事故" tabindex="-1">三、反事实学习（把&quot;设计&quot;变成&quot;事故&quot;） <a class="header-anchor" href="#三、反事实学习-把-设计-变成-事故" aria-label="Permalink to &quot;三、反事实学习（把&quot;设计&quot;变成&quot;事故&quot;）&quot;">​</a></h2><h3 id="怎么做-1" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做-1" aria-label="Permalink to &quot;怎么做&quot;">​</a></h3><p>看到任何一个机制，问一句：<strong>如果把它删掉，系统会在什么场景下坏掉？坏成什么样？</strong></p><table tabindex="0"><thead><tr><th>机制</th><th>删掉之后</th></tr></thead><tbody><tr><td>虚拟内存</td><td>两个程序都写 0x1000 地址 &gt; 互相覆盖 &gt; 一个程序崩溃能带崩另一个</td></tr><tr><td>页表</td><td>每次访存都要算&quot;虚拟地址对应物理哪&quot;，算一次要几十条指令 &gt; 程序慢十倍</td></tr><tr><td>TCP 的滑动窗口</td><td>每发一个包都要停下等确认 &gt; 带宽利用率极低</td></tr><tr><td>数据库的 undo log</td><td>事务回滚时无法还原旧值；MVCC 也没有旧版本可读</td></tr><tr><td>索引</td><td>每次查询全表扫描 &gt; 千万行表查一次几秒</td></tr></tbody></table><h3 id="为什么有效-1" tabindex="-1">为什么有效 <a class="header-anchor" href="#为什么有效-1" aria-label="Permalink to &quot;为什么有效&quot;">​</a></h3><p><strong>&quot;功能&quot;记不住，&quot;事故&quot;记得住</strong>。人对损失和故障的记忆强度远高于对定义的记忆。 而且这条思路直接对应面试的第三层追问——你练的就是考题。</p><h3 id="什么时候失效-1" tabindex="-1">什么时候失效 <a class="header-anchor" href="#什么时候失效-1" aria-label="Permalink to &quot;什么时候失效&quot;">​</a></h3><p>当机制的存在理由是&quot;性能&quot;而不是&quot;正确性&quot;时，反事实会显得不痛不痒（&quot;慢一点而已&quot;）。 这时候要把它<strong>量化</strong>：慢多少倍？在什么数据量下开始疼？有了数字才有痛感。</p><hr><h2 id="四、联系图谱-以问题为节点-不以章节为节点" tabindex="-1">四、联系图谱（以问题为节点，不以章节为节点） <a class="header-anchor" href="#四、联系图谱-以问题为节点-不以章节为节点" aria-label="Permalink to &quot;四、联系图谱（以问题为节点，不以章节为节点）&quot;">​</a></h2><h3 id="怎么做-2" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做-2" aria-label="Permalink to &quot;怎么做&quot;">​</a></h3><p>不要按&quot;第几章第几节&quot;记，按<strong>问题</strong>记。一个问题往往横跨四个模块：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>问题：我的程序为什么卡住了？</span></span>
<span class="line"><span>+- 是不是在等锁？        &gt; OS 的互斥锁 / 数据库的行锁</span></span>
<span class="line"><span>+- 是不是在等 IO？       &gt; OS 的阻塞 IO / 网络的对端没回</span></span>
<span class="line"><span>+- 是不是在等 CPU？      &gt; OS 的调度队列太长</span></span>
<span class="line"><span>+- 是不是在等 GC？       &gt; 语言运行时</span></span>
<span class="line"><span>+- 是不是在等数据库？    &gt; 慢 SQL / 锁等待 / 连接池打满</span></span></code></pre></div><p>一个&quot;卡住&quot;，把 OS、网络、数据库全串起来了。这样记住的东西，是以&quot;现象&quot;为索引的，比以&quot;章节&quot;为索引牢固得多。</p><h3 id="具体做法" tabindex="-1">具体做法 <a class="header-anchor" href="#具体做法" aria-label="Permalink to &quot;具体做法&quot;">​</a></h3><ol><li>每学完一个模块，画一张该模块内部的图（导读篇里已经给了）。</li><li>每学完四个模块，画一张总图（<a href="/study-hub/bagu/summary/00">一张图串起全部</a>）。</li><li>新学的概念，<strong>必须能挂到已有的图上</strong>。挂不上去，说明它是孤立的，两周后会忘。</li></ol><h3 id="什么时候失效-2" tabindex="-1">什么时候失效 <a class="header-anchor" href="#什么时候失效-2" aria-label="Permalink to &quot;什么时候失效&quot;">​</a></h3><p>图谱容易变成&quot;画得好看但没用&quot;。判断标准：<strong>合上图画不出来，就是没用</strong>。 所以图要自己画，不要收藏别人的。</p><hr><h2 id="五、费曼输出-讲给外行听" tabindex="-1">五、费曼输出（讲给外行听） <a class="header-anchor" href="#五、费曼输出-讲给外行听" aria-label="Permalink to &quot;五、费曼输出（讲给外行听）&quot;">​</a></h2><h3 id="怎么做-3" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做-3" aria-label="Permalink to &quot;怎么做&quot;">​</a></h3><p>找一个完全不懂技术的人（或者假装有），用<strong>不用术语</strong>的方式讲 3 分钟。</p><p>规则：</p><ul><li>不许说&quot;因为它是异步的&quot;这种话——&quot;异步&quot;本身就是需要解释的词。</li><li>讲到卡住的地方，<strong>立刻停下来记下</strong>，那就是你的漏洞。</li><li>讲完让对方提一个问题。对方的问题往往正好戳在你的模糊处。</li></ul><h3 id="为什么有效-2" tabindex="-1">为什么有效 <a class="header-anchor" href="#为什么有效-2" aria-label="Permalink to &quot;为什么有效&quot;">​</a></h3><p>&quot;理解&quot;的感觉很容易骗人——读的时候每个字都认识，就以为懂了。 但<strong>输出会强制你把并行的、模糊的直觉，压成一条线性的、明确的句子</strong>。压不出来的部分，就是没懂的部分。</p><h3 id="什么时候失效-3" tabindex="-1">什么时候失效 <a class="header-anchor" href="#什么时候失效-3" aria-label="Permalink to &quot;什么时候失效&quot;">​</a></h3><p>讲得太顺的时候要警惕：可能你在背，而不是在讲。 判断方法：换一个角度问自己同一个问题，还能答上来吗？只能从一个入口进，说明是背的。</p><hr><h2 id="六、主动回忆-间隔重复" tabindex="-1">六、主动回忆 + 间隔重复 <a class="header-anchor" href="#六、主动回忆-间隔重复" aria-label="Permalink to &quot;六、主动回忆 + 间隔重复&quot;">​</a></h2><h3 id="怎么做-4" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做-4" aria-label="Permalink to &quot;怎么做&quot;">​</a></h3><ul><li><strong>先回忆，再看答案</strong>。每篇末尾的自测 3 问，先合上书答，答完再展开。</li><li><strong>间隔回看</strong>：学完当天、第 3 天、第 7 天、第 15 天各回看一次（每次只要 5 分钟，看验收清单就行）。</li><li><strong>不要重读</strong>。重读的熟悉感是假的，它只让你认识字，不让你会答。</li></ul><p>时间表（和 28 天打卡表配合）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Day N    学 &gt; 当天晚上合书回忆 5min</span></span>
<span class="line"><span>Day N+1  打卡表里的&quot;复习昨日 15min&quot;</span></span>
<span class="line"><span>Day N+3  翻一眼验收清单，看还能不能勾</span></span>
<span class="line"><span>Day N+7  周复盘日，重做周验收</span></span>
<span class="line"><span>Day N+15 月度自测卷里会再考一次</span></span></code></pre></div><h3 id="为什么有效-3" tabindex="-1">为什么有效 <a class="header-anchor" href="#为什么有效-3" aria-label="Permalink to &quot;为什么有效&quot;">​</a></h3><p>回忆的过程本身就是加固，而重读只是&quot;识别&quot;。<strong>识别 ≠ 提取</strong>，面试考的是提取。</p><h3 id="什么时候失效-4" tabindex="-1">什么时候失效 <a class="header-anchor" href="#什么时候失效-4" aria-label="Permalink to &quot;什么时候失效&quot;">​</a></h3><p>回忆时&quot;感觉很熟但说不出来&quot;——这不是会了，这是最危险的状态。 必须逼自己<strong>说出完整的句子</strong>，哪怕说得磕巴。</p><hr><h2 id="七、动手验证-把抽象变成可见" tabindex="-1">七、动手验证（把抽象变成可见） <a class="header-anchor" href="#七、动手验证-把抽象变成可见" aria-label="Permalink to &quot;七、动手验证（把抽象变成可见）&quot;">​</a></h2><h3 id="怎么做-5" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做-5" aria-label="Permalink to &quot;怎么做&quot;">​</a></h3><p>有些概念光看文字永远隔一层，跑一下命令就通了：</p><table tabindex="0"><thead><tr><th>想搞懂</th><th>跑什么</th><th>看什么</th></tr></thead><tbody><tr><td>进程到底是什么</td><td><code>ps aux</code> / <code>top</code></td><td>每个进程有独立 PID、独立内存占用</td></tr><tr><td>线程共享什么</td><td><code>top -H -p &lt;pid&gt;</code></td><td>一个进程下多个线程，共享同一块内存</td></tr><tr><td>虚拟内存</td><td><code>cat /proc/&lt;pid&gt;/maps</code></td><td>每个进程的地址空间都是从 0 开始的假地址</td></tr><tr><td>缺页</td><td><code>ps -o min_flt,maj_flt -p &lt;pid&gt;</code></td><td>缺页次数在涨，说明真的在&quot;按需取&quot;</td></tr><tr><td>TCP 握手</td><td><code>tcpdump -i any port 80</code></td><td>肉眼看到 SYN / SYN-ACK / ACK</td></tr><tr><td>TIME_WAIT</td><td>\`ss -tan</td><td>grep TIME-WAIT\`</td></tr><tr><td>索引有没有用</td><td><code>EXPLAIN</code> 一条 SQL</td><td>type 从 ALL 变 ref，就是走了索引</td></tr><tr><td>缓存局部性</td><td>同一个算法用数组和链表各跑一遍</td><td>数组快几倍，且和数据量非线性</td></tr></tbody></table><h3 id="为什么有效-4" tabindex="-1">为什么有效 <a class="header-anchor" href="#为什么有效-4" aria-label="Permalink to &quot;为什么有效&quot;">​</a></h3><p><strong>看得见的东西不会忘</strong>。而且动手会暴露你的理解偏差——你以为的&quot;按需加载&quot;，实际跑起来发现缺页次数远比你想象的多。</p><h3 id="什么时候失效-5" tabindex="-1">什么时候失效 <a class="header-anchor" href="#什么时候失效-5" aria-label="Permalink to &quot;什么时候失效&quot;">​</a></h3><p>Windows 上很多命令没有（<code>tcpdump</code>、<code>/proc</code>）。 替代方案：装个 WSL，或者用 Docker 起个 Linux 容器，五分钟的事，值得。</p><hr><h2 id="八、记录类比的边界-防止-自我感觉懂了" tabindex="-1">八、记录类比的边界（防止&quot;自我感觉懂了&quot;） <a class="header-anchor" href="#八、记录类比的边界-防止-自我感觉懂了" aria-label="Permalink to &quot;八、记录类比的边界（防止&quot;自我感觉懂了&quot;）&quot;">​</a></h2><h3 id="怎么做-6" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做-6" aria-label="Permalink to &quot;怎么做&quot;">​</a></h3><p>每篇末尾都有「类比失效处 / 易错点」。<strong>这一节不是凑数的，是防止你把比喻当结论</strong>。</p><p>比如&quot;内存 = 操作台&quot;这个类比的失效处：</p><ul><li>操作台上的东西是<strong>连续的</strong>，内存是<strong>分页的、可以不连续</strong>的。</li><li>操作台拿东西不需要&quot;翻译地址&quot;，内存访问要过页表。</li><li>操作台不会&quot;把不用的菜暂时收走&quot;，内存会（换出到磁盘）。</li></ul><h3 id="为什么有效-5" tabindex="-1">为什么有效 <a class="header-anchor" href="#为什么有效-5" aria-label="Permalink to &quot;为什么有效&quot;">​</a></h3><p>大部分&quot;以为自己懂了&quot;的时刻，都是类比在细节处悄悄失效，而你没察觉。 <strong>主动写下失效点，等于给类比装了个护栏</strong>。</p><hr><h2 id="九、把方法串起来-一次完整的学习循环" tabindex="-1">九、把方法串起来：一次完整的学习循环 <a class="header-anchor" href="#九、把方法串起来-一次完整的学习循环" aria-label="Permalink to &quot;九、把方法串起来：一次完整的学习循环&quot;">​</a></h2><p>以「虚拟内存」为例，走一遍全套流程：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 读之前：先问&quot;内存不够用会怎样&quot;（反事实）</span></span>
<span class="line"><span>2. 读的时候：用&quot;操作台 / 仓库&quot;这套类比（类比域）</span></span>
<span class="line"><span>3. 读完画图：虚拟地址 &gt; 页表 &gt; 物理地址（联系图谱）</span></span>
<span class="line"><span>4. 追问三层：是什么（地址翻译）/ 为什么（隔离 + 超卖）/ 不这样（互相踩内存）（追问三层）</span></span>
<span class="line"><span>5. 动手：cat /proc/self/maps，看到自己进程的假地址（动手验证）</span></span>
<span class="line"><span>6. 输出：讲给外行听——&quot;每个程序都以为自己独占一整台机器&quot;（费曼）</span></span>
<span class="line"><span>7. 记边界：页表本身也占内存，多级页表就是为了省这个（类比边界）</span></span>
<span class="line"><span>8. 3/7/15 天后回看验收清单（间隔重复）</span></span></code></pre></div><p>八步走完，这篇基本长在脑子上了。<strong>不用每篇都走八步</strong>，但&quot;追问三层&quot;和&quot;动手验证&quot;这两步，每篇都别省。</p><hr><h2 id="十、最后-关于-枯燥" tabindex="-1">十、最后：关于&quot;枯燥&quot; <a class="header-anchor" href="#十、最后-关于-枯燥" aria-label="Permalink to &quot;十、最后：关于&quot;枯燥&quot;&quot;">​</a></h2><p>枯燥感通常来自两个地方：</p><ol><li><strong>不知道这东西有什么用</strong> &gt; 用反事实法，先想&quot;没有它会怎样&quot;，痛点出来了就不枯燥了。</li><li><strong>信息是散的，接不上</strong> &gt; 用类比域和联系图谱，把它挂到已有的网上。</li></ol><p>如果一篇读起来还是很枯燥，通常说明<strong>这篇的前置知识你缺了</strong>，而不是这篇写得差。 这时候别硬啃，回去看导读篇，把前置补上。</p><h2 id="✅-验收清单" tabindex="-1">✅ 验收清单 <a class="header-anchor" href="#✅-验收清单" aria-label="Permalink to &quot;✅ 验收清单&quot;">​</a></h2><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="0"> 能说出&quot;三个钩子&quot;分别是什么（向上、横向、向下），并拿一个概念现场挂一遍</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="1"> 能说出三套类比域各自对应哪个模块，并解释&quot;为什么类比不能换来换去&quot;</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="2"> 能对任意一个知识点，说出它的第 2 层（为什么这样设计）和第 3 层（不这样会怎么坏）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="3"> 能说出&quot;重读&quot;和&quot;主动回忆&quot;的区别，以及为什么重读会产生&quot;假懂&quot;</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="4"> 能说出至少 3 个可以动手验证的命令（如 <code>ps</code> / <code>tcpdump</code> / <code>EXPLAIN</code>）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="5"> 合上书，用自己的话讲 3 分钟，中途不卡壳</li></ul>`,97)])])}const q=a(e,[["render",r]]);export{c as __pageData,q as default};
